def P(s, style='BodyX'):
    return Paragraph(s,styles[style])
def table(data,widths,header=True,repeat=1, font=7.7):
    t=Table(data,colWidths=widths,repeatRows=repeat if header else 0,hAlign='LEFT')
    cmds=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,LINE),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]
    if header: cmds += [('BACKGROUND',(0,0),(-1,0),INK),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
    for row in range(1 if header else 0,len(data)):
        if row%2==0: cmds.append(('BACKGROUND',(0,row),(-1,row),PALE))
    t.setStyle(TableStyle(cmds)); return t
def cells(row,header=False): return [P(str(x), 'CellHeadX' if header else 'CellX') for x in row]
def bullet(s): return P('&bull;&nbsp; '+s)
def header_footer(canvas,doc):
    canvas.saveState(); w,h=A4
    if doc.page>1:
        canvas.setStrokeColor(LINE); canvas.setLineWidth(.5); canvas.line(18*mm,h-15*mm,w-18*mm,h-15*mm)
        canvas.setFont('Helvetica',7.5);canvas.setFillColor(MUTED);canvas.drawString(18*mm,h-11.5*mm,'SMART REFRIGERATOR MANAGER  |  CN7021')
        canvas.drawRightString(w-18*mm,10*mm,f'{doc.page}')
    canvas.restoreState()
def build(path,story):
    doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=22*mm,bottomMargin=17*mm,title=path.stem,author='Smart Refrigerator Manager Project Team')
    doc.build(story,onFirstPage=header_footer,onLaterPages=header_footer)

