s += [P('1 Introduction','H1X'),P('This document describes the next planned release of the existing Smart Refrigerator Manager web application. The product currently manages a signed-in user’s food inventory using a Java 21 / Spring Boot application, Thymeleaf pages, browser JavaScript, Spring Data JPA, and a relational database. The enhancement is intended to reduce language friction, make food disposal visible, and help users choose meals based on current stock. The proposed work is a continuation of the existing project, not the future Flutter QR scanning application. [1, 2]','BodyX'),P('Purpose and scope','H2X'),P('Release 2 covers English/Japanese localization, a user-owned waste history, inventory-aware menu recommendations, registration with email, profile preferences, and email OTP password recovery. Flutter mobile scanning, barcode/QR intake, external grocery integrations, nutrition/allergen advice, and production AI service deployment are deferred.','BodyX'),P('Audience and reading order','H2X'),P('Developers should read Sections 2-5 first; ScrumDesk users should use Sections 6-8; testers should use Section 9; assessors should use Sections 10-12 and the evidence checklist. Requirements are uniquely identified to support traceability, consistent with requirements engineering practice. [3]','BodyX'),P('Current state and improvement rationale','H2X'),P('The existing application separates controllers, services, repositories, entities, and static browser code. Login and registration exist, but the registration model has no email address; the interface is Japanese; deleting food leaves no audit record; and there is no menu suggestion endpoint. The extension introduces service boundaries for waste history and menu generation while retaining the existing layered architecture. This is a substantive backend and data-model enhancement, rather than a UI-only change.','BodyX')]

s += [P('2 Product description and architecture','H1X'),P('User classes','H2X'),table([cells(['User','Needs'],True),cells(['Household member','Manage own stock, choose language, record waste, get suggestions, maintain profile and recover access.']),cells(['Project maintainer','Review code, configure database/mail/optional AI service, monitor errors and maintain localized text.']),cells(['Assessment team','Trace backlog, requirements, implementation evidence, tests, contribution and cost assumptions.'])],[44*mm,117*mm])]
s += [P('Architecture and responsibility boundaries','H2X'),P('Browser pages call authenticated JSON endpoints. Controllers enforce request boundaries and obtain the authenticated principal. Services apply account ownership, waste recording, recommendation selection, and profile/reset rules. Repositories persist user, food and waste-event data. The recommendation module calls an OpenAI-compatible chat-completions endpoint only when AI_API_KEY is configured; otherwise it ranks a small local recipe catalogue against English/Japanese ingredient aliases. This seam isolates provider calls and keeps the default local path usable. Spring Data JPA supplies repository abstractions; Spring Security supplies authentication and password encoding. [4, 5, 6]','BodyX')]
arch=[[P('Browser UI','CellHeadX'),P('REST controllers','CellHeadX'),P('Application services','CellHeadX'),P('JPA repositories','CellHeadX'),P('Relational DB','CellHeadX')],[P('i18n, profile, inventory, waste, menus','CellX'),P('/api/profile, /api/waste, /api/menu-suggestions','CellX'),P('UserService, WasteService, MenuSuggestionService','CellX'),P('UserRepository, FoodRepository, WasteEventRepository','CellX'),P('users, foods, waste_events','CellX')]]
